def _github_username(profile_github_url):
    """Last path segment of the profile URL, as markdown_sync._active_github_username did."""
    github_url = (profile_github_url or "").rstrip("/")
    path_parts = [part for part in urlparse(github_url).path.split("/") if part]
    return path_parts[-1] if path_parts else None


def backfill_github_url(apps, schema_editor):
    """Store the repo URL the removed fallback derived from the active profile and slug."""
    Project = apps.get_model("main", "Project")
    PortfolioProfile = apps.get_model("main", "PortfolioProfile")

    # Same as PortfolioProfile.get_active(): an unsaved default when none is active.
    profile = PortfolioProfile.objects.filter(is_active=True).first() or PortfolioProfile()
    username = _github_username(profile.github_url)
    if not username:
        return

    projects = (
        Project.objects.filter(blog=True)
        .filter(Q(github_url__isnull=True) | Q(github_url=""))
        .exclude(Q(blog_url__isnull=True) | Q(blog_url=""))
    )
    for project in projects:
        repo = BLOG_REPO_PATHS.get(project.blog_url, project.blog_url)
        project.github_url = f"https://github.com/{username}/{repo}"
        project.save(update_fields=["github_url"])


